 <!-- SweetAlert2 (محلي - بدلاً من CDN لتجنب طلب الشبكة في كل صفحة) -->
 <script src="http://127.0.0.1:8000/js/libs/sweetalert2.all.min.js"></script>
 <script>
 window.confirmAction = function(elementOrAction, messageOrForm, ev) {
 // Stop any event bubbling or default actions explicitly
 try {
 var e = ev || window.event;
 if (e && typeof e.preventDefault === 'function') {
 e.preventDefault();
 e.stopPropagation();
 }
 } catch (err) {}
 
 // Immediately hide any loader that might have been shown
 if (typeof window.hidePageLoader === 'function') {
 window.hidePageLoader();
 }
 
 var targetElement = null;
 var message = '';
 
 // Handle signature: confirmAction(formOrButton, 'message', event)
 if (typeof elementOrAction === 'object' && elementOrAction !== null) {
 targetElement = elementOrAction;
 message = typeof messageOrForm === 'string' ? messageOrForm : (targetElement.getAttribute('data-confirm-message') || 'هل أنت متأكد من تنفيذ هذا الإجراء؟');
 } 
 // Handle signature: confirmAction('actionName', form)
 else if (typeof elementOrAction === 'string') {
 message = elementOrAction;
 if (typeof messageOrForm === 'object' && messageOrForm !== null) {
 targetElement = messageOrForm;
 }
 }
 
 // Determine action context for tailored styling
 var msgLower = (message || '').toLowerCase();
 var isDelete = /حذف|إلغاء نهائي|مسح|delete|destroy/i.test(msgLower);
 var isRevert = /رجوع|تراجع|تحويل.*مسودة|إلغاء الاعتماد|rollback|revert/i.test(msgLower);
 var isDisable = /تعطيل|إيقاف|disable/i.test(msgLower);
 var isEnable = /تفعيل|تمكين|enable/i.test(msgLower);
 var isApprove = /موافق|اعتماد|تأكيد|إرسال|إغلاق المسودة|قفل|approve|finalize|submit/i.test(msgLower);
 
 var title = 'تأكيد العملية';
 var icon = 'warning';
 var confirmBtnClass = 'btn-primary';
 var confirmBtnIcon = 'fa-check';
 var confirmBtnText = 'نعم، استمرار';
 
 if (isDelete) {
 title = 'تأكيد عملية الحذف';
 icon = 'warning';
 confirmBtnClass = 'btn-danger';
 confirmBtnIcon = 'fa-trash-alt';
 confirmBtnText = 'نعم، حذف';
 } else if (isDisable) {
 title = 'تأكيد عملية التعطيل';
 icon = 'warning';
 confirmBtnClass = 'btn-warning';
 confirmBtnIcon = 'fa-pause-circle';
 confirmBtnText = 'نعم، تعطيل';
 } else if (isEnable) {
 title = 'تأكيد عملية التفعيل';
 icon = 'question';
 confirmBtnClass = 'btn-success';
 confirmBtnIcon = 'fa-check-circle';
 confirmBtnText = 'نعم، تفعيل';
 } else if (isRevert) {
 title = 'تأكيد الرجوع إلى مسودة';
 icon = 'warning';
 confirmBtnClass = 'btn-warning';
 confirmBtnIcon = 'fa-undo-alt';
 confirmBtnText = 'نعم، تراجع';
 } else if (isApprove) {
 title = 'تأكيد العملية';
 icon = 'question';
 confirmBtnClass = 'btn-primary';
 confirmBtnIcon = 'fa-check-double';
 confirmBtnText = 'نعم، تأكيد';
 }
 
 if (typeof Swal !== 'undefined') {
 Swal.fire({
 title: title,
 text: message || 'هل أنت متأكد؟',
 icon: icon,
 showCancelButton: true,
 confirmButtonText: `<i class="fas ${confirmBtnIcon} me-1"></i> ${confirmBtnText}`,
 cancelButtonText: '<i class="fas fa-times me-1"></i> إلغاء',
 customClass: {
 confirmButton: `btn ${confirmBtnClass} px-4 fw-bold`,
 cancelButton: 'btn btn-light text-dark px-4 border'
 },
 buttonsStyling: true,
 reverseButtons: true
 }).then((result) => {
 if (result.isConfirmed && targetElement) {
 if (targetElement.tagName === 'FORM') {
 targetElement.classList.add('no-loader');
 targetElement.onsubmit = null;
 targetElement.submit();
 } else if ((targetElement.tagName === 'BUTTON' || targetElement.tagName === 'INPUT') && targetElement.form) {
 targetElement.form.classList.add('no-loader');
 targetElement.form.onsubmit = null;
 targetElement.form.submit();
 } else if (targetElement.tagName === 'A' && targetElement.href && !targetElement.href.startsWith('javascript:')) {
 targetElement.classList.add('no-loader');
 window.location.href = targetElement.href;
 } else if (typeof targetElement.submit === 'function') {
 targetElement.submit();
 }
 }
 });
 return false;
 } else {
 if (confirm(message)) {
 if (targetElement) {
 if (targetElement.tagName === 'FORM') targetElement.submit();
 else if (targetElement.form) targetElement.form.submit();
 else if (targetElement.tagName === 'A' && targetElement.href) window.location.href = targetElement.href;
 }
 return true;
 }
 return false;
 }
 };
 </script>


 <script src="http://127.0.0.1:8000/js/libs/bootstrap.bundle.min.js"></script>



 <script>
 (function ($) {
 'use strict';

 /* ─── Utility: derive a custom-field name from a select's name attr ─── */
 function customNameFor(selectName) {
 // e.g. "beneficiary_groups[]" → "custom_beneficiary_group_name"
 if (selectName.indexOf('beneficiary_groups') !== -1) {
 return 'custom_beneficiary_group_name';
 }
 // e.g. "program_id" → "custom_program_name"
 // e.g. "financings[0][financing_type_id]" → "financings[0][custom_financing_type_name]"
 // e.g. "preliminary_activities[0][procedures][0][costs][0][financial_item_id]" → …[custom_financial_item_name]
 return selectName.replace(/([a-z_]+)_id(\]?)$/, 'custom_$1_name$2');
 }

 /* ─── Insert or retrieve the custom-input wrapper after the select ─── */
 function getOrCreateCustomInput($select) {
 // 1) If a static Blade wrapper is declared via data-custom-wrapper-id, use it
 var staticWrapperId = $select.data('custom-wrapper-id');
 if (staticWrapperId) {
 var $static = $('#' + staticWrapperId);
 if ($static.length) return $static;
 }

 // 2) Otherwise use/create a dynamic wrapper keyed to this element
 var wrapperId = 'other-wrapper-' + $select.attr('id');
 if (!wrapperId || wrapperId === 'other-wrapper-undefined') {
 wrapperId = $select.data('other-wrapper-id');
 if (!wrapperId) {
 wrapperId = 'other-wrapper-' + Math.random().toString(36).slice(2, 9);
 $select.data('other-wrapper-id', wrapperId);
 }
 }

 var $existing = $('#' + wrapperId);
 if ($existing.length) return $existing;

 var selectName = $select.attr('name') || '';
 var customFieldName = customNameFor(selectName);
 var ajaxType = $select.data('ajax-type') || '';

 // Human-readable label map
 var labelMap = {
 program: 'اسم البرنامج الجديد',
 priority: 'اسم الأولوية الجديدة',
 domain: 'اسم المجال الجديد',
 subdomain: 'اسم المجال الفرعي الجديد',
 intervention: 'اسم التدخل الجديد',
 beneficiary_group: 'اسم الفئة المستفيدة الجديدة',
 authority: 'اسم الجهة الجديدة',
 financial_item: 'اسم البند المالي الجديد',
 unit: 'اسم الوحدة الجديدة',
 financing_type: 'اسم نوع التمويل الجديد',
 financing_form: 'اسم شكل التمويل الجديد',
 sub_financing_form: 'اسم الشكل الفرعي الجديد',
 funding_source: 'اسم مصدر التمويل الجديد',
 internal_entity: 'اسم الجهة الداخلية الجديدة',
 directorate: 'اسم المديرية الجديدة',
 sub_area: 'اسم المنطقة الفرعية الجديدة',
 };
 var label = labelMap[ajaxType] || 'القيمة الجديدة';

 var $wrapper = $('<div>', {
 id: wrapperId,
 class: 'custom-other-wrapper mt-2',
 style: 'display:none'
 }).html(
 '<label class="form-label small text-primary fw-semibold">' +
 '<i class="fas fa-plus-circle me-1"></i>' + label +
 ' <span class="text-danger">*</span></label>' +
 '<input type="text" name="' + customFieldName + '"' +
 ' class="form-control form-control-sm custom-other-input"' +
 ' placeholder="أدخل ' + label + '...">' +
 '<small class="text-muted" style="font-size:0.72rem;">' +
 ' <i class="fas fa-clock me-1"></i>سيُحفظ بانتظار المراجعة والاعتماد.' +
 '</small>'
 );

 // Insert right after the Select2 container (or the original select if no S2)
 var $s2Container = $select.next('.select2-container');
 if ($s2Container.length) {
 $s2Container.after($wrapper);
 } else {
 $select.after($wrapper);
 }

 return $wrapper;
 }

 /* ─── Show / hide the custom input for a given select ─── */
 function updateOtherField($select) {
 var val = $select.val();
 var text = $select.find('option:selected').text().trim();
 var isOther = (val === 'other' || text === 'غير ذلك');

 var $wrapper = getOrCreateCustomInput($select);
 var $input = $wrapper.find('.custom-other-input');

 if (isOther) {
 $wrapper.slideDown(180);
 $input.prop('required', true);
 } else {
 $wrapper.slideUp(180);
 $input.prop('required', false).val('');
 }
 }

 /* ─── Listen on every Select2 change (covers dynamic rows too) ─── */
 $(document).on('select2:select select2:unselect change', 'select[data-ajax-type]', function () {
 updateOtherField($(this));
 });

 /* ─── On page ready: initialise for selects already set to "other" ─── */
 $(document).ready(function () {
 $('select[data-ajax-type]').each(function () {
 var $sel = $(this);
 var val = $sel.val();
 var text = $sel.find('option:selected').text().trim();
 if (val === 'other' || text === 'غير ذلك') {
 updateOtherField($sel);
 }
 });
 });

 /* ─── Re-scan when new rows are added dynamically (financing, cost rows) ─── */
 var observer = new MutationObserver(function (mutations) {
 mutations.forEach(function (m) {
 m.addedNodes.forEach(function (node) {
 if (node.nodeType !== 1) return;
 $(node).find('select[data-ajax-type]').addBack('select[data-ajax-type]').each(function () {
 var $sel = $(this);
 // Small delay so Select2 has time to init on the new row
 setTimeout(function () {
 var val = $sel.val();
 var text = $sel.find('option:selected').text().trim();
 if (val === 'other' || text === 'غير ذلك') {
 updateOtherField($sel);
 }
 }, 400);
 });
 });
 });
 });

 observer.observe(document.body, { childList: true, subtree: true });

 })(jQuery);
 </script>

